function validate(input) {
  const [content] = input;
  if (typeof content !== 'string' || content.length > 10000) return 'content must be text of at most 10,000 characters.';
  if (content === '') return null;
  const rows = (content.endsWith('\n') ? content.slice(0, -1) : content).split('\n');
  let width = -1;
  for (const row of rows) {
    if (!/^[\x21-\x7e]+( [\x21-\x7e]+)*$/.test(row)) return 'Each row needs fields of printable characters separated by single spaces.';
    const fields = row.split(' ').length;
    if (width !== -1 && fields !== width) return 'Every row must have the same number of fields.';
    width = fields;
  }
  return null;
}

