function transposeFile(content) {
  // Read field by field, appending each field to the output line of its column, as the awk script does.
  const lines = [];
  let field = '', col = 0, firstRow = true;
  const finish = () => {
    if (firstRow) lines.push(field);
    else lines[col] += ' ' + field;
    field = '';
  };
  for (let i = 0; i < content.length; i++) {
    const ch = content[i];
    if (ch === ' ') { finish(); col += 1; }
    else if (ch === '\n') { finish(); col = 0; firstRow = false; }
    else field += ch;
  }
  if (content !== '' && !content.endsWith('\n')) finish();
  return lines.join('\n');
}

