function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789-.,:_ABC';
  const field = () => {
    let text = '';
    const length = 1 + pick(size === 'small' ? 3 : 4);
    for (let i = 0; i < length; i++) text += alphabet[pick(alphabet.length)];
    return text;
  };
  let rows, cols;
  const shape = rand();
  if (size === 'small') {
    if (shape < 0.1) return [''];
    rows = 1 + pick(4);
    cols = 1 + pick(4);
  } else if (shape < 0.2) {
    rows = 1 + pick(3);
    cols = 100 + pick(300);
  } else if (shape < 0.4) {
    rows = 100 + pick(300);
    cols = 1 + pick(3);
  } else {
    rows = 10 + pick(31);
    cols = 10 + pick(31);
  }
  const lines = [];
  for (let r = 0; r < rows; r++) lines.push(Array.from({ length: cols }, field).join(' '));
  return [lines.join('\n') + (rand() < 0.5 ? '\n' : '')];
}
